// Generated from index.html by build-engine.cjs. Do not edit by hand.
export function createEngine(directory){
let state=structuredClone(directory),decks=new Map();
const uid=()=>crypto.randomUUID();
// TEMPLATE_CORE_START
function inputGroups(value=''){if(typeof value!=='string'||value.length>2000)throw Error('Entry input must be a string of at most 2,000 characters.');if(!value.trim())return [[]];const groups=value.split('||').map(part=>part.split('&&').map(x=>x.trim()));if(groups.flat().some(x=>!x)||groups.flat().length>50)throw Error('Use && for every value or || for alternatives; every value must be nonblank (maximum 50).');return groups;}
function requiredInputs(value=''){return [...new Set(inputGroups(value).flat())];}
function normalizeInputs(values=[]){if(!Array.isArray(values)||values.length>100||values.some(v=>typeof v!=='string'||v.length>2000))throw Error('Inputs must be up to 100 strings of at most 2,000 characters.');return [...new Set(values.map(v=>v.trim()).filter(Boolean))];}
function parseRollInput(value){const parts=value.split(/\s+\|\s*input:\s*/);if(parts.length===1)return {table:value.trim(),inputs:[]};if(parts.length!==2||!parts[0].trim()||!parts[1].trim())throw Error('Invalid roll input syntax.');const inputs=[];let rest=parts[1];while(rest.trim()){const m=rest.match(/^\s*("(?:[^"\\]|\\.)*"|[A-Za-z_]\w*)\s*(,|$)/);if(!m)throw Error('Inputs must be variables or double-quoted strings, separated by commas.');inputs.push(m[1].startsWith('"')?{literal:JSON.parse(m[1])}:{variable:m[1]});rest=rest.slice(m[0].length);if(m[2]&&!rest.trim())throw Error('Missing input after comma.');}if(inputs.length>100)throw Error('Limit: 100 input arguments.');return {table:parts[0].trim(),inputs};}

function validateTemplates(raw){if(raw.templates===undefined)return;const ids=new Set();if(!Array.isArray(raw.templates)||raw.templates.length>200)throw Error('Limit: 200 templates.');for(const t of raw.templates){if(!t||typeof t.id!=='string'||ids.has(t.id)||typeof t.name!=='string'||typeof t.source!=='string'||t.source.length>200000||typeof (t.folder||'')!=='string')throw Error('Invalid template.');ids.add(t.id);if(t.refs!==undefined&&(!t.refs||typeof t.refs!=='object'||Array.isArray(t.refs)||Object.values(t.refs).some(id=>typeof id!=='string')))throw Error('Invalid template references.');}}
function parseTemplate(source){if(typeof source!=='string'||source.length>200000)throw Error('Template limit: 200,000 characters.');const tokens=source.split(/(\{\{[\s\S]*?\}\})/g),root=[],stack=[{body:root}];for(const token of tokens){if(!token)continue;const top=()=>stack.at(-1);if(!token.startsWith('{{')){if(token.includes('{{')||token.includes('}}'))throw Error('Unclosed template token.');top().body.push({type:'text',value:token});continue;}const cmd=token.slice(2,-2).trim();let m;if(cmd==='end'){if(stack.length===1)throw Error('Unexpected {{end}}.');stack.pop();continue;}if(cmd==='else'){if(stack.length===1||top().node.type==='repeat'||top().elseUsed)throw Error('Unexpected {{else}}.');top().elseUsed=true;top().body=top().node.other;continue;}let node;if((m=cmd.match(/^if\s+([A-Za-z_]\w*)\s*(!=|=|contains)\s*(.+)$/))){node={type:'if',alias:m[1],op:m[2],value:m[3],body:[],other:[]};}else if((m=cmd.match(/^chance\s+(\d+(?:\.\d+)?)$/))){if(+m[1]>100)throw Error('Chance must be 0–100.');node={type:'chance',percent:+m[1],body:[],other:[]};}else if((m=cmd.match(/^repeat\s+(\d+)$/))){if(+m[1]<1||+m[1]>1000)throw Error('Repeat must be 1–1,000.');node={type:'repeat',count:+m[1],body:[],other:[]};}if(node){top().body.push(node);if(stack.length>=20)throw Error('Template nesting limit: 20.');stack.push({node,body:node.body});continue;}if((m=cmd.match(/^pick\s+([A-Za-z_]\w*)(?:\s+(\d+)(?:\.\.(\d+))?)?(?:\s+with\s+([A-Za-z_]\w*))?\s*=\s*(.+)$/))){const options=m[5].split('|').map(x=>x.trim()),min=+(m[2]||1),max=+(m[3]||m[2]||1);if(options.some(x=>!x)||new Set(options.map(x=>x.toLowerCase())).size!==options.length||options.length>100||min<1||max<min||max>options.length)throw Error('Pick requires 1–100 unique options and a valid count range.');top().body.push({type:'pick',alias:m[1],min,max,required:m[4],options});}else if((m=cmd.match(/^draw\s+([A-Za-z_]\w*)\s*=\s*(.+)$/))){top().body.push({type:'draw',alias:m[1],...parseRollInput(m[2])});}else if((m=cmd.match(/^roll\s+([A-Za-z_]\w*)\s*=\s*(.+)$/))){top().body.push({type:'roll',alias:m[1],...parseRollInput(m[2])});}else if((m=cmd.match(/^table:\s*(.+)$/))){top().body.push({type:'table',...parseRollInput(m[1])});}else if((m=cmd.match(/^dice:\s*(\d{1,3}d\d{1,7}(?:[+-]\d{1,7})?)$/i))){const d=m[1].match(/^(\d+)d(\d+)/i);if(+d[1]<1||+d[1]>100||+d[2]<1||+d[2]>1000000)throw Error('Dice limits: 1–100 dice, 1–1,000,000 sides.');top().body.push({type:'dice',value:m[1]});}else if(/^[A-Za-z_]\w*$/.test(cmd)){top().body.push({type:'variable',alias:cmd});}else throw Error('Unknown template token: '+cmd);}if(stack.length!==1)throw Error('Missing {{end}} for '+stack.at(-1).node.type+'.');return root;}
function templateTables(nodes){return nodes.flatMap(n=>n.table?[n.table]:n.body?[...templateTables(n.body),...templateTables(n.other)]:[]);}
function bindTemplate(t){const refs={...t.refs};for(const name of templateTables(parseTemplate(t.source))){if(refs[name])continue;const matches=state.tables.filter(x=>x.id===name||x.name===name);if(matches.length===1)refs[name]=matches[0].id;}t.refs=refs;return t;}
function runTemplate(template){const nodes=parseTemplate(template.source),variables=Object.create(null),inputValues=Object.create(null),lists=new Map(),rolls=[],draw={policy:'repeat',used:new Map(),trace:[],context:new Map()},budget={remaining:5000,draw};let steps=0,characters=0;function resolve(name){const id=template.refs?.[name];const matches=id?state.tables.filter(t=>t.id===id):state.tables.filter(t=>t.id===name||t.name===name);if(matches.length!==1)throw Error((matches.length?'Ambiguous':'Missing')+' table: '+name);return matches[0];}function roll(name,alias,inputs=[]){const t=resolve(name);let list;if(alias){list=lists.get(alias);if(list&&list.id!==t.id)throw Error('A draw list must use the same table: '+alias);if(!list){list={id:t.id,texts:[],draw:{policy:'unique',used:new Map(),trace:draw.trace,context:draw.context}};lists.set(alias,list);}const seen=list.draw.used.get(t.id);if(!t.entries.some((e,i)=>eligible(e,draw.context,inputs)&&!seen?.keys.has(i)))throw Error('No unused entries remain in draw list: '+alias);}if(budget.remaining<=0)throw Error('Template limit: 5,000 table expansions.');const start=draw.trace.length;let text;budget.draw=list?.draw||draw;budget.draw.inputs=inputs;try{text=rollTable(t.id,[],budget);}finally{budget.draw=draw;draw.inputs=[];}if(budget.remaining<0)throw Error('Template limit: 5,000 table expansions.');rolls.push({tableId:t.id,name:t.name,text,choices:draw.trace.slice(start)});if(list){list.texts.push(text);inputValues[alias]=[...list.texts];return list.texts.join(', ');}return text;}function rollInputs(n){return normalizeInputs((n.inputs||[]).flatMap(x=>{if(x.literal!==undefined)return [x.literal];if(!(x.variable in variables))throw Error("Input uses an unassigned variable: "+x.variable);return inputValues[x.variable]||[variables[x.variable]];}));}function emit(value){characters+=value.length;if(characters>1000000)throw Error('Template output exceeds 1 MB.');return value;}function walk(list){let text='';for(const n of list){if(++steps>30000)throw Error('Template execution limit reached.');if(n.type==='text')text+=emit(n.value);else if(n.type==='roll'){variables[n.alias]=roll(n.table,undefined,rollInputs(n));inputValues[n.alias]=[variables[n.alias]];}else if(n.type==='draw')variables[n.alias]=roll(n.table,n.alias,rollInputs(n));else if(n.type==='pick'){const pool=[...n.options],chosen=[];if(n.required){if(!(n.required in variables))throw Error('Pick requires an assigned variable: '+n.required);const i=pool.findIndex(x=>x.toLowerCase()===variables[n.required].toLowerCase());if(i<0)throw Error('Required pick value is not an option: '+n.required);chosen.push(pool.splice(i,1)[0]);}const count=n.min+randomInt(n.max-n.min+1);while(chosen.length<count)chosen.push(pool.splice(randomInt(pool.length),1)[0]);variables[n.alias]=chosen.join(', ');inputValues[n.alias]=chosen;}else if(n.type==='table')text+=emit(roll(n.table,undefined,rollInputs(n)));else if(n.type==='dice')text+=emit(dice('[['+n.value+']]'));else if(n.type==='variable'){if(!(n.alias in variables))throw Error('Variable has not been rolled: '+n.alias);text+=emit(variables[n.alias]);}else if(n.type==='repeat'){for(let i=0;i<n.count;i++)text+=walk(n.body);}else if(n.type==='chance')text+=walk(randomInt(1000000)<n.percent*10000?n.body:n.other);else {if(!(n.alias in variables))throw Error('Condition uses an unrolled variable: '+n.alias);const a=variables[n.alias].toLowerCase(),b=n.value.toLowerCase();const pass=n.op==='='?a===b:n.op==='!='?a!==b:a.includes(b);text+=walk(pass?n.body:n.other);}}return text;}const text=walk(nodes).replace(/\n[ \t]*\n(?:[ \t]*\n)+/g,'\n\n').trim();return {templateId:template.id,name:template.name,text,variables,rolls,rollCount:draw.trace.length};}

function validate(raw){validateTemplates(raw||{});if(raw?.folders!==undefined&&(!Array.isArray(raw.folders)||raw.folders.length>5000||raw.folders.some(x=>typeof x!=='string')))throw Error('Invalid folders.');if(!raw||raw.version!==1||!Array.isArray(raw.tables)||!raw.tables.length||raw.tables.length>5000)throw Error('Expected a Table Forge version 1 JSON collection (1–5,000 tables).');let ids=new Set();for(const t of raw.tables){if(!t||typeof t.id!=='string'||ids.has(t.id)||typeof t.name!=='string'||!Array.isArray(t.entries)||t.entries.length>10000)throw Error('Invalid or duplicate table data.');ids.add(t.id);for(const e of t.entries){if(e?.input!==undefined)requiredInputs(e.input);if(!e||typeof e.text!=='string'||!Number.isSafeInteger(e.weight)||e.weight<1||e.weight>1000000||(e.subtable!=null&&typeof e.subtable!=='string'))throw Error('Entries need text and an integer weight from 1 to 1,000,000.');}}for(const t of raw.tables)for(const e of t.entries)if(e.subtable&&!ids.has(e.subtable))throw Error('A sub-table reference is missing from the backup.');if(raw.generators!==undefined){if(!Array.isArray(raw.generators)||raw.generators.length>100)throw Error('Invalid saved generators.');const gids=new Set();for(const g of raw.generators){if(!g||typeof g.id!=='string'||gids.has(g.id)||typeof g.name!=='string')throw Error('Invalid generator identity.');gids.add(g.id);validateSetup(g,ids);}}
if(raw.notebook!==undefined&&(!Array.isArray(raw.notebook)||raw.notebook.length>1000||raw.notebook.some(n=>!n||typeof n.title!=='string'||typeof n.text!=='string'||typeof n.notes!=='string')))throw Error('Invalid notebook.');
for(const t of raw.tables){if(t.folder!==undefined&&typeof t.folder!=='string')throw Error('Invalid folder.');if(t.tags!==undefined&&(!Array.isArray(t.tags)||t.tags.some(x=>typeof x!=='string')))throw Error('Invalid tags.');}

for(const t of raw.tables)for(const e of t.entries)if(e.refs!==undefined){if(!e.refs||typeof e.refs!=='object'||Array.isArray(e.refs)||Object.values(e.refs).some(id=>typeof id!=='string'||!ids.has(id)))throw Error('Invalid inline table references.');}for(const t of raw.tables)for(const e of t.entries){if(e.conditionMode!==undefined&&!['all','any'].includes(e.conditionMode))throw Error('Invalid condition mode.');if(e.conditions!==undefined&&(!Array.isArray(e.conditions)||e.conditions.length>50||e.conditions.some(c=>!c||typeof c.tableId!=='string'||(c.tableId&&!ids.has(c.tableId))||!['equals','contains','notEquals'].includes(c.op)||typeof c.value!=='string'||!c.value.trim())))throw Error('Invalid entry conditions.');}return raw;}

function validateSetup(g,ids=new Set(state.tables.map(t=>t.id))){normalizeInputs(g.inputs);if(!['single','linked','meta'].includes(g.mode)||!Number.isInteger(g.batch)||g.batch<1||g.batch>50)throw Error('Choose a valid mode and 1–50 results.');if(g.drawPolicy&&!['repeat','unique','deck'].includes(g.drawPolicy))throw Error('Invalid repeat rule.');const groups=g.mode==='meta'?g.combinations:[{tables:g.tables,weight:1}];if(!Array.isArray(groups)||!groups.length||groups.length>100)throw Error('Add between 1 and 100 combinations.');for(const c of groups){if(!Number.isInteger(c.weight)||c.weight<1||c.weight>1000000)throw Error('Combination weights must be 1–1,000,000.');if(g.mode==='meta'&&(typeof c.name!=='string'||!c.name.trim()))throw Error('Give each combination a name.');if(!Array.isArray(c.tables)||!c.tables.length||c.tables.length>200)throw Error('Select at least one table in each combination.');let count=0;for(const p of c.tables){if(!ids.has(p.id)||!Number.isInteger(p.count)||p.count<1||p.count>20)throw Error('A table is missing or a roll count is outside 1–20.');count+=p.count;}if(count>200)throw Error('Choose at most 200 table rolls in a combination.');}return g;}
function chooseWeighted(items){let ticket=randomInt(items.reduce((sum,e)=>sum+e.weight,0));for(const e of items){ticket-=e.weight;if(ticket<0)return e;}return items[items.length-1];}
function randomInt(n){const max=4294967296;if(n<=max){let v;const a=new Uint32Array(1);const cap=max-max%n;do{crypto.getRandomValues(a);v=a[0];}while(v>=cap);return v%n;}return Math.floor(Math.random()*n);}
function dice(text){return text.replace(/\[\[(\d{1,3})d(\d{1,7})([+-]\d{1,7})?\]\]/gi,(match,n,s,m)=>{n=+n;s=+s;if(n<1||n>100||s<1||s>1000000)return '[dice limits exceeded]';let total=Number(m||0);for(let i=0;i<n;i++)total+=randomInt(s)+1;return String(total);});}
function eligible(e,context,inputs=[]){if(!inputGroups(e.input).some(group=>group.every(value=>inputs.includes(value))))return false;if(!e.conditions?.length)return true;const matches=c=>{const values=context.get(c.tableId)||[];if(!values.length)return false;const value=c.value.toLocaleLowerCase();return c.op==='notEquals'?values.every(x=>x.toLocaleLowerCase()!==value):values.some(x=>c.op==='contains'?x.toLocaleLowerCase().includes(value):x.toLocaleLowerCase()===value);};return e.conditionMode==='any'?e.conditions.some(matches):e.conditions.every(matches);}
function recordChoice(context,id,text){if(!context.has(id))context.set(id,[]);context.get(id).push(text);}
function rollTable(id,path=[],budget={remaining:200}){if(--budget.remaining<0)return '[reference expansion limit reached]';const t=state.tables.find(t=>t.id===id);if(!t)return '[missing table]';if(path.includes(id))return `[circular link stopped: ${t.name}]`;if(path.length>=20)return '[maximum sub-table depth reached]';if(!t.entries.length)return `[${t.name}: no entries]`;const draw=budget.draw||{policy:'repeat',used:new Map(),trace:[]},pool=draw.policy==='deck'?decks:draw.used;let seen=pool.get(id);const signature=JSON.stringify(t.entries);if(!seen||seen.signature!==signature){seen={signature,keys:new Set()};if(draw.policy!=='repeat')pool.set(id,seen);}draw.context=draw.context||new Map();budget.draw=draw;const qualifying=t.entries.map((e,i)=>({...e,index:i})).filter(e=>eligible(e,draw.context,draw.inputs||[]));if(!qualifying.length)return `[${t.name}: no entries match earlier rolls or inputs]`;const available=qualifying.filter(e=>draw.policy==='repeat'||!seen.keys.has(e.index));if(!available.length)return `[${t.name}: exhausted — ${draw.policy==='deck'?'reset decks':'start a new batch'}]`;const chosen=chooseWeighted(available);if(draw.policy!=='repeat')seen.keys.add(chosen.index);draw.trace.push({id,index:chosen.index,signature,choice:chosen.text});recordChoice(draw.context,id,chosen.text);const next=[...path,id];let text=dice(chosen.text).replace(refPattern,(_,name)=>{let target=chosen.refs?.[name];if(!target){const matches=state.tables.filter(t=>t.name===name);if(matches.length!==1)return `[${matches.length?'ambiguous':'missing'} table: ${name}]`;target=matches[0].id;}return rollTable(target,next,budget);})||'(blank entry)';if(chosen.subtable)text+=' → '+rollTable(chosen.subtable,next,budget);if(text.length>1000000)throw Error('Roll output exceeds 1 MB.');return text;}
function runSetup(setup){validateSetup(setup);const draw={inputs:normalizeInputs(setup.inputs),policy:setup.drawPolicy||'repeat',used:new Map(),trace:[]},batchId=uid(),results=[];for(let n=0;n<setup.batch;n++){draw.context=new Map();const combination=setup.mode==='meta'?chooseWeighted(setup.combinations):null,parts=[];for(const spec of combination?combination.tables:setup.tables){const t=state.tables.find(t=>t.id===spec.id);for(let i=0;i<spec.count;i++){draw.trace=[];const text=rollTable(t.id,[],{remaining:200,draw});parts.push({tableId:t.id,name:t.name,text,locked:false,draws:[...draw.trace]});}}results.push({time:new Date().toLocaleTimeString(),batchId,policy:draw.policy,inputs:[...draw.inputs],combination:combination?.name||'',parts});}return results;}
const refPattern=/(?<!\[)\[([^\[\]\n]+)\](?!\])/g;
validate(state);
return {
 catalog(){return {tables:state.tables.map(t=>({id:t.id,name:t.name,folder:t.folder||'',entries:t.entries.length})),generators:(state.generators||[]).map(g=>({id:g.id,name:g.name,mode:g.mode})),templates:(state.templates||[]).map(t=>({id:t.id,name:t.name,folder:t.folder||''}))};},
 generate(request){if(!request||typeof request.id!=='string')throw Error('Provide a request type and id.');if(request.type==='template'){const t=state.templates?.find(t=>t.id===request.id);if(!t)throw Error('Template not found.');return runTemplate(t);}if(request.type==='generator'){const g=state.generators?.find(g=>g.id===request.id);if(!g)throw Error('Generator not found.');return {results:runSetup({...g,batch:request.batch??g.batch,inputs:request.inputs??g.inputs})};}if(request.type==='table'){if(!state.tables.some(t=>t.id===request.id))throw Error('Table not found.');return {results:runSetup({mode:'single',tables:[{id:request.id,count:1}],batch:request.batch??1,drawPolicy:'repeat',inputs:request.inputs})};}throw Error('Type must be table, generator, or template.');}
};
}
